func TestMemoryTraces(t *testing.T) {
	ctx := context.Background()
	target, exp, err := NewMemoryTracing(ctx, zipkin.TracingConfig{ServiceName: "front"})
	if err != nil {
		t.Fatal(err)
	}
	backTarget, _, _ := NewMemoryTracing(ctx, zipkin.TracingConfig{ServiceName: "back"})
	defer func() { _ = backTarget.Handle.Shutdown(ctx) }()

	// front/root → back/query (cross-service, recorded through the same exporter).
	ctx1, root := target.Handle.Tracer("t").Start(ctx, "root", trace.WithAttributes())
	time.Sleep(20 * time.Millisecond)
	_, child := backTarget.Handle.Tracer("t").Start(ctx1, "query")
	child.End()
	root.End()
	_ = target.Handle.ForceFlush(ctx)
	_ = backTarget.Handle.ForceFlush(ctx)
	backSpans := backTarget.Query.(*MemoryTraceQuery).exporter.Spans()
	// Merge the back-end span into the front exporter so one query sees both.
	exp.mu.Lock()
	exp.spans = append(exp.spans, backSpans...)
	exp.mu.Unlock()
	q := target.Query
	tid := root.SpanContext().TraceID().String()

	tr, err := q.GetTrace(ctx, tid)
	if err != nil || len(tr.Spans) != 2 {
		t.Fatalf("GetTrace = %+v %v", tr, err)
	}
	if tr, err := q.GetTrace(ctx, "abc"); tr != nil || err != nil {
		t.Fatal("missing trace should be nil")
	}
	if _, err := q.GetTrace(ctx, "xyz"); !errors.Is(err, zipkin.ErrValidation) {
		t.Fatal("bad id accepted")
	}
	cctx, cancel := context.WithCancel(ctx)
	cancel()
	if _, err := q.GetTrace(cctx, tid); !errors.Is(err, zipkin.ErrCancelled) {
		t.Fatal("cancelled get")
	}
	if _, err := q.SearchTraces(cctx, zipkin.TraceSearchQuery{}); !errors.Is(err, zipkin.ErrCancelled) {
		t.Fatal("cancelled search")
	}

	// a second, older trace with a tag
	_, other := target.Handle.Tracer("t").Start(ctx, "other", trace.WithNewRoot())
	other.SetAttributes()
	other.End()
	_ = target.Handle.ForceFlush(ctx)

	search := func(qq zipkin.TraceSearchQuery) []zipkin.TraceSummary {
		t.Helper()
		out, err := q.SearchTraces(ctx, qq)
		if err != nil {
			t.Fatal(err)
		}
		return out
	}
	if all := search(zipkin.TraceSearchQuery{}); len(all) != 2 || all[0].RootName != "other" {
		t.Fatalf("all = %+v", all)
	}
	if got := search(zipkin.TraceSearchQuery{Service: "back", Operation: "query"}); len(got) != 1 || got[0].RootName != "root" || got[0].SpanCount != 2 || got[0].RootServiceName != "front" {
		t.Fatalf("by service = %+v", got)
	}
	if got := search(zipkin.TraceSearchQuery{Operation: "nope"}); len(got) != 0 {
		t.Fatal("operation filter")
	}
	if got := search(zipkin.TraceSearchQuery{Tags: map[string]string{"x": "y"}}); len(got) != 0 {
		t.Fatal("tag filter")
	}
	if got := search(zipkin.TraceSearchQuery{Limit: 1}); len(got) != 1 {
		t.Fatal("limit")
	}
	if got := search(zipkin.TraceSearchQuery{MinDuration: time.Hour}); len(got) != 0 {
		t.Fatal("min duration")
	}
	if got := search(zipkin.TraceSearchQuery{MaxDuration: 10 * time.Millisecond}); len(got) != 1 {
		t.Fatalf("max duration = %+v", got)
	}
	future := time.Now().Add(time.Hour)
	if got := search(zipkin.TraceSearchQuery{Start: future}); len(got) != 0 {
		t.Fatal("start filter")
	}
	if got := search(zipkin.TraceSearchQuery{End: time.Unix(0, 0)}); len(got) != 0 {
		t.Fatal("end filter")
	}
	if !tagsMatch(map[string]any{"n": int64(1)}, map[string]string{"n": "1"}) || tagsMatch(map[string]any{}, map[string]string{"n": "1"}) {
		t.Fatal("tagsMatch")
	}

	if s, _ := q.ListServices(ctx); len(s) != 2 || s[0] != "back" {
		t.Fatalf("services = %v", s)
	}
	if ops, _ := q.ListOperations(ctx, "front"); len(ops) != 2 || ops[0] != "other" {
		t.Fatalf("operations = %v", ops)
	}
	deps, _ := q.GetDependencies(ctx, zipkin.DependencyOptions{})
	if len(deps) != 1 || deps[0] != (zipkin.DependencyLink{Parent: "front", Child: "back", CallCount: 1}) {
		t.Fatalf("deps = %+v", deps)
	}
	if deps, _ := q.GetDependencies(ctx, zipkin.DependencyOptions{Start: future}); len(deps) != 0 {
		t.Fatal("deps start filter")
	}
	if deps, _ := q.GetDependencies(ctx, zipkin.DependencyOptions{End: time.Unix(0, 0)}); len(deps) != 0 {
		t.Fatal("deps end filter")
	}
	if _, err := q.WaitForTrace(ctx, tid, zipkin.WaitForTraceOptions{MinSpans: 2}); err != nil {
		t.Fatal(err)
	}
	if s := Summarize("t", nil); s.SpanCount != 0 || s.TraceID != "t" {
		t.Fatal("Summarize empty")
	}
}

func TestMemorySpanExporter(t *testing.T) {
	ctx := context.Background()
	e := NewMemorySpanExporter()
	cctx, cancel := context.WithCancel(ctx)
	cancel()
	if err := e.ExportSpans(cctx, nil); err == nil {
		t.Fatal("cancelled export")
	}
	boom := errors.New("boom")
	e.FailNext(boom)
	if err := e.ExportSpans(ctx, nil); !errors.Is(err, boom) {
		t.Fatal("FailNext")
	}
	_ = e.Shutdown(ctx)
	if err := e.ExportSpans(ctx, nil); err != nil || !e.IsShutdown() {
		t.Fatal("export after shutdown")
	}
	e.Reset()
	if e.IsShutdown() || len(e.Spans()) != 0 {
		t.Fatal("Reset")
	}
}
